class Solution {
public:
    string build(string& text) {
        string out;
        for (int i = 0; i < (int)text.size(); i++) {
            if (text[i] == '#') {
                if (!out.empty()) out.pop_back();
            } else {
                out.push_back(text[i]);
            }
        }
        return out;
    }
    bool backspaceCompare(string s, string t) {
        string a = build(s);
        string b = build(t);
        return a == b;
    }
};
